window.RONKO_I18N = {"ko":{"common.skip":"본문으로 건너뛰기","common.menu":"메뉴 열기","common.brandSub":"문화를 읽는 정육인","common.brandFull":"Ron Ko · 문화를 읽는 정육인","common.location":"대한민국 고양","common.langLabel":"언어 선택","common.langMenu":"언어","nav.home":"홈","nav.about":"소개","nav.archive":"아카이브","nav.contact":"문의","meta.index.title":"Ron Ko — 정육 명인 · 한우 오마카세 셰프 · 육류 컨설턴트","meta.index.desc":"고용재(Ron) — 18년차 정육 명인이자 그릴마스터, 한우 오마카세 셰프, 홍콩·싱가포르·라오스에서 활동한 한국한우협회 공식 강사, 그리고 국내 푸드테크 스타트업의 CPO. 세계 각지에서 컨설팅과 마스터클래스, 주방 오픈을 진행합니다.","meta.index.ogTitle":"Ron Ko — 문화를 읽는 정육인","meta.index.ogDesc":"정육 명인, 한우 오마카세 셰프, 글로벌 육류 컨설턴트. 싱가포르에서 보스턴까지 이어진 세미나, 그리고 도마 앞에서 보낸 18년.","meta.about.title":"소개 · Ron Ko — 문화를 읽는 정육인","meta.about.desc":"고용재(Ron) — 31년의 일: 기업 구매·BPR 10년, 금융 컨설팅 5년, 그리고 정육인·그릴마스터·한우 오마카세 셰프로 보낸 18년.","meta.archive.title":"아카이브 · Ron Ko — 문화를 읽는 정육인","meta.archive.desc":"Ron Ko의 작업 기록: 홍콩·싱가포르·라오스의 한우 세미나, 보스턴의 한식 바비큐 주방, 정육 현장, 그리고 쉬는 날.","meta.contact.title":"문의 · Ron Ko — 문화를 읽는 정육인","meta.contact.desc":"한우 세미나, 정육 마스터클래스, 주방 오픈, 육류 프로그램, 제품 컨설팅 문의 — 고용재(Ron)에게 연락하세요.","home.hero.kicker":"고용재 · Ron","home.hero.title":"정육 명인. 한우 오마카세 셰프. <em>육류 컨설턴트.</em>","home.hero.lede":"일한 31년 중 18년을 칼과 함께 보냈습니다. 한국에서 가장 까다로운 한우 다이닝의 육부를 맡았고, 서울 강남 한우다이닝 울릉에서 오마카세 카운터를 이끌었으며, 지금은 푸드테크 공장의 제품과 시스템을 만들고 있습니다. 오늘은 싱가포르에서 보스턴까지, 파트너를 위해 가르치고 자르고 굽습니다.","home.hero.ctaWork":"함께 일하기","home.hero.ctaArchive":"아카이브 보기","home.hero.foot":"경기도 고양 거주 · 세미나, 컨설팅, 주방 오픈 문의 가능","home.hero.alt":"흑백 사진. 매달린 소 도체 앞에서 칼을 대는 Ron Ko","home.hero.caption":"매달린 도체를 발골하는 중. 이 일이 무엇이 되든 — 코스가 되고, 공장이 되고, 브랜드가 되어도 — 시작은 언제나 여기입니다.","home.m1":"정육인·그릴마스터·헤드셰프로 보낸 세월","home.m2":"년의 경력, 그중 13년은 기업 구매·BPR·금융","home.m3":"울릉도 전통 한우 칡소를 위해 오간 입도","home.m4":"가르치고, 컨설팅하고, 주방을 연 국가·지역","home.work.eyebrow":"글로벌 프로젝트와 출장","home.work.title":"일이 나를 데려간 곳, 2025–2026","home.work.intro":"2년 동안 네 개 지역: 싱가포르의 대사관 리셉션과 루프탑 그릴, 홍콩의 정육 시연, 보스턴의 한식 바비큐 주방 오픈, 그리고 동남아시아 곳곳의 세미나와 시장 방문.","home.sg.when":"2026 · 10월","home.sg.title":"한우, 대사관 리셉션에서 루프탑 그릴까지","home.sg.place":"싱가포르","home.sg.body":"주싱가포르 한국대사관, 비드푸드(Bidfood), 현지 유통사와 함께한 5일. 마지막은 야외 마스터클래스였습니다. 손님들은 등심 한 덩이가 부위별로 나뉘는 과정을 지켜본 뒤, 그 자리에서 구워 먹었습니다.","home.sg.f1":"주싱가포르 한국대사관 — 개천절 리셉션, 한우 부스 운영과 서비스","home.sg.f2":"비드푸드 싱가포르 — 구매팀 대상 쇼룸 세션","home.sg.f3":"유통사 매대 점검 — 훈연 이베리코와 오리","home.sg.f4":"야외 한우 마스터클래스와 저녁 그릴 시식","home.sg.link":"싱가포르 사진 보기","home.sg.alt1":"싱가포르의 초록색 HANWOO KOREAN BEEF 배너 아래에서 열린 저녁 시식회, 한우를 굽는 셰프들","home.sg.alt2":"싱가포르 루프탑 테라스에서 한우 등심 한 덩이를 자르는 Ron Ko","home.sg.alt3":"주싱가포르 한국대사관 리셉션의 HANWOO 부스에 선 Ron Ko","home.hk.when":"2026 · 6월","home.hk.title":"셰프와 바이어를 위한 정육 시연","home.hk.place":"홍콩","home.hk.body":"한국한우협회 세미나 프로그램 중 제가 맡은 부분입니다. 39개 부위를 칼을 들고, 메뉴에 무엇이 올라갈지 결정하는 셰프·수입사·바이어 앞에서 설명합니다.","home.hk.f1":"무대 위에서 대분할 해체, 셰프복과 장갑 차림으로","home.hk.f2":"대분할에서 세분할, 다시 서비스 컷까지 — 잘리는 순서대로 설명","home.hk.f3":"호스트 주방과 함께한 플레이팅과 시식","home.hk.link":"홍콩 사진 보기","home.hk.alt1":"검은 셰프복을 입고 홍콩에서 한우 대분할 해체를 시연하는 Ron Ko","home.hk.alt2":"시연을 마치고 객석을 향해 손을 흔드는 Ron Ko와 호스트 셰프","home.hk.alt3":"홍콩 세미나를 마친 뒤 주최 측과 셰프들 사이에 선 Ron Ko","home.us.when":"2026 · 3월 & 5월","home.us.title":"해외 한식 바비큐 주방 오픈","home.us.place":"미국 보스턴·뉴욕","home.us.body":"보스턴에서는 JIN-JEE 팀과 레시피로는 옮길 수 없는 것들을 함께했습니다. 통근육 손질, 숙성, 그릴 매뉴얼, 주방 동선, 그리고 그 아래의 원가 구조까지. 2026년 3월 뉴욕은 별도의 출장이었고, 그때의 사진도 여기에 함께 둡니다.","home.us.f1":"JIN-JEE 보스턴 — 손질·숙성·그릴 기법을 주방팀에 전수","home.us.f2":"주방 라인, 화덕, 홀 동선 점검","home.us.f3":"2026년 3월 뉴욕 — 필름과 폰으로 남긴 도시","home.us.link":"미국 사진 보기","home.us.alt1":"보스턴 JIN-JEE의 주방 라인과 화덕, 필름 촬영","home.us.alt2":"보스턴에서 JIN-JEE 팀과 함께한 저녁 식사","home.us.alt3":"호텔 창으로 본 맨해튼의 야경","home.sea.when":"2025 · 4월 & 10월","home.sea.title":"동남아시아 세미나와 시장 방문","home.sea.place":"라오스 · 캄보디아 · 태국","home.sea.body":"미국 출장 전해의 일입니다. 라오스에서는 부위를 직접 들고 한우 세미나를 했고, 2025년 4월에는 프놈펜과 방콕을 오갔습니다. 행사장, 쇼룸, 그리고 그 사이의 평범한 골목들.","home.sea.f1":"라오스 — 한우 세미나, 2025년 10월","home.sea.f2":"캄보디아 — 프놈펜 행사장·쇼룸 방문, 2025년 4월","home.sea.f3":"태국 — 방콕, 2025년 4월","home.sea.link":"동남아시아 사진 보기","home.sea.alt1":"라오스 세미나에서 한우 대분할육을 보여주며 발표하는 Ron Ko","home.sea.alt2":"프놈펜 세미나 행사장의 대형 스크린","home.sea.alt3":"2025년 출장 중 방문한 방콕의 호텔 정원","home.chapters.eyebrow":"대표 경력","home.chapters.title":"18년, 챕터로 나누면","home.chapters.intro":"날짜까지 담은 전체 이력은 <a href=\"about.html\">소개</a> 페이지에 있습니다. 이 일곱 개의 장이 나머지를 가능하게 했습니다.","home.c1.years":"2018 · 2019","home.c1.title":"본앤브레드 — 육부장","home.c1.text":"한국에서 가장 까다로운 프리미엄 한우 다이닝에서 1++ 도체 선별, 정밀 해체, 특수부위와 숙성을 맡았습니다. 오마카세 서비스 중 객석 앞에서 갈비 한 덩이를 통째로 발골하던 일도 그중 하나입니다.","home.c2.years":"2019 · 2022","home.c2.title":"순우블랙과 한우다이닝 울릉","home.c2.text":"명동 순우블랙 4층 지점을 열고 최상층 오마카세 카운터를 맡았습니다. 이어 서울 강남의 한우다이닝 울릉으로 옮겨 오마카세 코스를 직접 기획하고 집도했습니다. 부위를 중심으로 코스를 짜고, 손님 앞에서 잘라 냅니다.","home.c3.years":"2020 · 2022","home.c3.title":"울릉도, 열여섯 번의 항해","home.c3.text":"2년, 열여섯 번의 뱃길, 목적은 하나였습니다. 울릉도 전통 한우 칡소. 섬 도축장에서 직접 대분할육을 발골·정형해 배로 내륙에 공수했고, 그 고기가 서울 강남 한우다이닝 울릉의 카운터에 올랐습니다. 중간에 중개인은 없었습니다.","home.c4.years":"2022 · 2023","home.c4.title":"광평미트 — 이사","home.c4.text":"건식 숙성실 두 곳, 샤퀴테리, 소시지와 생햄, 냉축 맛돈 런칭, 그리고 외식 브랜드와 명절 선물세트로 이어지는 소·돼지 공급.","home.c5.years":"2023 · 현재","home.c5.title":"푸드테크 스타트업 — CPO·파트너 이사","home.c5.text":"저당·고단백 가열식 불고기 라인 — 100g당 당류 1.6g, 단백질 최대 39g — 과 HACCP 공장, 그리고 AI로 혼자 만든 공장 ERP·현장 앱. 입고부터 로트 추적, 배치별 실시간 원가까지 457커밋.","home.c6.years":"2024 · 계속","home.c6.title":"R&D와 시식 카운터","home.c6.text":"규격서에서 시식 카운터까지 제품을 끌어올리는 일 — 가열식 제품 라인, 숙성·샤퀴테리 프로그램, 그 뒤의 OEM 공급까지. 정육인과 제품 책임자가 결국 같은 사람이라는 사실이 여기서 드러납니다.","home.c7.years":"2026 · 집필 중","home.c7.title":"육류 인문학 아카이브 집필","home.c7.text":"육류의 역사를 다룬 7편의 연구 — 가축화, 근대 이전 한국의 돼지고기, 품종 개량, 그리고 이 나라가 왜 소고기를 얇게 썰어 직화로 굽는가 — 와 그 위에 쓰고 있는 원고.","home.wide.caption":"시식·상담 부스 — 규격서가 손님의 입맛을 만나는, 이 일의 제품 쪽 면.","home.wide.meta":"대한민국 · 2024.07","home.wide.alt":"식품 박람회의 제품 시식·상담 부스, 카운터 뒤에 선 팀","home.services.eyebrow":"하는 일","home.services.title":"세 가지, 같은 손으로","home.s1.title":"정육과 육류 프로그램","home.s1.text":"도체 해체, 수율과 원가, 건식·습식 숙성, 샤퀴테리 — 그리고 제가 주방에 서 있지 않을 때도 맛이 흔들리지 않게 만드는 표준 작업 절차까지.","home.s1.i1":"도체·대분할 해체","home.s1.i2":"숙성, 샤퀴테리, 염지","home.s1.i3":"수율·원가·메뉴 구조","home.s2.title":"한우 마스터클래스와 세미나","home.s2.text":"셰프, 수입사, 유통사, 무역 행사를 위해 칼을 들고 부위를 설명합니다. 한국어로, 영어로, 또는 통역을 통해 — 한국한우협회와 함께 해외에서 진행하는 것과 같은 프로그램입니다.","home.s2.i1":"B2B 세미나와 무역 행사","home.s2.i2":"라이브 정육 시연","home.s2.i3":"셰프·바이어 교육","home.s3.title":"외식·제품 컨설팅","home.s3.text":"매장 오픈, 주방 동선, 그릴 매뉴얼, 원가 구조 — 그리고 제조 쪽에서는 가열식 제품 개발, HACCP 공정, 그 뒤를 받치는 디지털 시스템.","home.s3.i1":"주방·서비스 설계","home.s3.i2":"가열식(RTH)·OEM 제품 개발","home.s3.i3":"HACCP 공장 구축과 ERP","home.quote.text":"“한 민족의 역사는 짐승을 자르는 방식에 쓰여 있다.”","home.quote.cite":"육류 인문학 아카이브 · 집필 중","home.closing.p1":"마지막으로 만들고 싶은 것은 식당도 제품도 아닙니다. 한국인이 왜 소고기를 얇게 썰어 직화에 올리고, 짐승을 마지막 한 겹까지 먹는지를 다룬 책입니다. 민족적 자부심이 아니라 도마와 도축장, 그리고 사료에서 출발해 쓰고 있습니다.","home.closing.p2":"연구 7편은 끝났습니다. 품종의 역사, 근대 이전 한국의 돼지고기, ‘와규 원조’와 ‘삼겹살 수출’ 이야기의 사실관계, 옛 기록 속 소의 빛깔, 그리고 중국·유럽·한국이 각각 짐승을 어떻게 요리로 바꿨는가. 지금은 원고를 쓰고 있습니다.","home.closing.cta":"프로젝트 이야기 읽기","home.cta.eyebrow":"문의","home.cta.title":"고기 이야기를 나눌까요?","home.cta.text":"가르칠 세미나, 열 주방, 진열대에 올릴 제품, 혹은 객석에서 아무도 이름을 대지 못하는 부위 — 무엇을 하고 있는지 알려주시면 답장드립니다.","home.cta.more":"연락하는 다른 방법","about.eyebrow":"소개","about.title":"31년, 칼은 두 번째였습니다.","about.portraitAlt":"싱가포르 야외에서 한우 등심 한 덩이를 자르는 Ron Ko, 뒤로 싱가포르 스카이라인","about.portraitCaption":"2026년 10월, 싱가포르. 야외 마스터클래스에서 등심 한 덩이를 자르는 중.","about.p1":"일한 31년 중 처음 13년은 시스템 안에서 보냈습니다. 1995년부터 상장 건설회사 구매팀에서 철근, 레미콘, 후판, 하도급 입찰을 다뤘고, 이어 전사 BPR팀에서 모든 부서의 프로세스를 뜯어고쳐 다시 설계하고 전산에 올렸습니다. 2003년부터 2007년까지는 금융상품을 팔았습니다. 낯선 사람 앞에 앉아 어려운 것을 쉬운 말로 설명하는 법을 배운 시기입니다.","about.p2":"2007년 10월, 손으로 기술을 배우려고 정육점 문을 열고 들어갔습니다. 돼지 도체로 18개월, 소고기로 1년. 그다음은 공장과 플랜트, 다시 다이닝: 프리미엄 한우 하우스, 서울 강남 한우다이닝 울릉의 오마카세 카운터, 칡소를 위해 열여섯 번 다녀온 울릉도 도축장, 샤퀴테리 프로그램, 그리고 지금 제품을 총괄하는 푸드테크 스타트업.","about.p3":"사업을 곁들인 셰프도, 음식을 좋아하는 사업가도 아닙니다. 먼저 기업 시스템 안에서 10년을 보낸 정육인이고, 그 조합이 제 일입니다. 가르칠 수 있고, 원가를 계산할 수 있고, 문서로 남겨 반복할 수 있는 기술.","about.stat1":"년의 경력","about.stat2":"년을 칼과 함께","about.stat3":"년은 기업 시스템에서 먼저","about.timeline.eyebrow":"연혁","about.timeline.title":"순서대로 쓴 경력","about.timeline.intro":"모든 날짜는 실제로 시작하고 그만둔 달입니다. 비어 있는 구간은 곧은 길이 아니었기 때문입니다.","about.era1":"2023 — 현재","about.era2":"2013 — 2023","about.era3":"2007 — 2012","about.era4":"1995 — 2007","about.r1.years":"2023.12 – 현재","about.r1.role":"CPO·파트너 이사, 푸드테크 스타트업","about.r1.small":"저당·고단백 가열식 불고기 라인, HACCP 공장, AI로 혼자 만든 공장 ERP·현장 앱(457커밋).","about.r2.years":"2026 – 현재","about.r2.role":"육류 인문학 아카이브 집필","about.r2.small":"연구 7편 완료, 원고 집필 중.","about.r3.years":"2022.06 – 2023.11","about.r3.role":"광평미트 이사","about.r3.small":"건식 숙성실 두 곳, 샤퀴테리·소시지·생햄, 냉축 맛돈 런칭, 외식 브랜드와 명절 선물세트 공급.","about.r4.years":"2020.05 – 2022.06","about.r4.role":"한우다이닝 울릉 지점장","about.r4.small":"서울 강남 카운터에서 오마카세 코스를 기획·진행. 칡소를 위해 울릉도에 열여섯 번 입도, 도축장에서 직접 발골해 배로 내륙에 공수.","about.r5.years":"2019.08 – 2020.05","about.r5.role":"순우블랙 명동 지점장","about.r5.small":"4개 층 규모 지점을 열고 최상층 프리미엄 오마카세 카운터 운영.","about.r6.years":"2018.09 – 2019.08","about.r6.role":"본앤브레드 육부장","about.r6.small":"한국의 프리미엄 한우 하우스에서 1++ 선별, 정밀 도체 해체, 특수부위와 숙성.","about.r7.years":"2013 – 2018","about.r7.role":"독립 주방 시절","about.r7.small":"한식 바비큐 전문점 육부장(2014), 파주 셀프 바비큐 매장 운영(2015), 한우 다이닝 하우스 육부장·그릴 셰프(2016–17).","about.r8.years":"2012.03 – 2012.10","about.r8.role":"오센틱미트 공장장","about.r8.small":"패티, 수제 소시지, 스테이크 — 1·2차 가공, 공정과 위생.","about.r9.years":"2010.04 – 2011.12","about.r9.role":"지엠축산 생산팀장","about.r9.small":"하루 4~6마리 도체, 전용 공장에서 정밀 해체와 2차 가공.","about.r10.years":"2009.03 – 2010.03","about.r10.role":"아우림한우마을 육류팀장","about.r10.small":"정육식당용 한우 해체, 인근 산업단지 B2B 명절 선물세트.","about.r11.years":"2007.10 – 2009.03","about.r11.role":"교하고기마트 육부","about.r11.small":"시작한 곳: 돼지 도체 18개월, 소고기 1년.","about.r12.years":"2003.05 – 2007.09","about.r12.role":"ING생명 재정 컨설턴트","about.r12.small":"개인·법인 재무 설계.","about.r13.years":"1995.03 – 2003.04","about.r13.role":"고려개발(대림그룹) 구매·BPR","about.r13.small":"철근·콘크리트·후판 등 대량 원자재 구매, 이어 전사 프로세스 재설계와 그에 따른 ERP.","about.note":"학력: 명지대학교 무역학과(1989–1994). <a href=\"archive.html\">아카이브</a>에 사진으로 남은 출장 외에도, 홍콩·싱가포르·라오스에서 한국한우협회 공식 한우 강사로, 2026년 보스턴에서 K-BBQ 주방 컨설팅을 했습니다.","about.off.eyebrow":"일 밖에서","about.off.title":"관심사와 여행","about.off.intro":"도마 앞에 서 있지 않은 날을 채우는 것: 길, 코스, 필름, 그리고 가족.","about.cycling.label":"사이클","about.cycling.text":"주로 로드 사이클입니다. 아카이브의 오래된 사진은 미시령 정상에서 찍은 것이고, 지금도 그 오르막을 한 해의 기준으로 삼습니다.","about.cycling.alt":"라이딩 전 헬멧을 쓴 Ron Ko","about.golf.label":"골프","about.golf.text":"일정이 허락할 때마다. 하루가 망해도 바깥에서 네 시간을 보내는 유일한 운동입니다.","about.golf.alt":"골프장에 선 Ron Ko","about.film.label":"필름 사진","about.film.text":"낡은 필름 카메라는 늘 여행 가방에 들어갑니다. 이 사이트의 보스턴·뉴욕 사진 몇 장도 그 카메라로 찍었습니다.","about.film.alt":"오래된 필름 카메라를 든 Ron Ko","about.japan.label":"여행 · 일본 2025","about.japan.text":"가족과 나고야. 오후 내내 머물고 싶었던 칼 가게, 그리고 마쓰사카·다지마 소의 품종사 전시.","about.japan.alt":"나고야의 한 칼 가게 안","about.extra.p1":"커피는 드립입니다. 계속 돌아오는 두 봉지는 케냐 AA와 에티오피아 워시드 — 주방에서 무엇보다 물 온도로 먼저 따질 사람입니다.","about.extra.p2":"남는 시간은 <a href=\"archive.html#writing\">육류 인문학 아카이브</a>를 위한 독서로 갑니다. 옛 기록, 품종 등록부, 그리고 한 마을이 무엇을 먹었는지 적어 둔 사람들의 글.","about.quote.text":"“칼은 도구입니다. 손님이 기억할 부위를 아는 것이 이 일입니다.”","about.quote.cite":"Ron Ko","about.cta.contact":"연락하기","about.cta.archive":"아카이브 보기","archive.eyebrow":"아카이브","archive.title":"순서대로 남긴 기록","archive.lede":"세미나, 마스터클래스, 주방, 공장, 그리고 가끔의 휴일. 모든 사진에는 찍은 날과 장소가 붙어 있습니다. 날짜를 모르는 사진에는 날짜를 쓰지 않았습니다.","archive.filterLabel":"아카이브 필터","filter.all":"전체","filter.trips":"해외 출장·세미나","filter.craft":"정육·다이닝·R&D","filter.travel":"여행·취미","archive.empty":"사진을 준비 중입니다 — 곧 다시 확인해 주세요.","archive.writing.eyebrow":"글쓰기 · 육류 인문학 아카이브","archive.writing.title":"고기를 글로 쓰다","archive.writing.p1":"육류의 역사와 문화를 다루는 장기 프로젝트. 소와 돼지의 가축화에서 시작해, 한국의 요리사가 왜 소고기를 얇게 썰어 직화에 올리고 짐승을 마지막 한 겹까지 먹는지까지.","archive.writing.p2":"주장은 어느 나라 소고기가 최고라는 것이 아닙니다. 한 민족이 짐승을 자르고 굽고 먹는 방식에 그 역사가 담겨 있고, 그 기록은 반복해서 옮기기보다 가까이 읽혀야 한다는 것입니다.","archive.status.research":"연구","archive.status.researchText":"연구 7편 완료, 주제별로 정리 — 품종과 토종 축, 근대 이전 한국의 돼지고기, 옛 기록, ‘와규 원조’·‘삼겹살 수출’ 이야기의 사료 대조, 정육과 조리법.","archive.status.manuscript":"원고","archive.status.manuscriptText":"서문과 프롤로그 초고를 쓰고, 장마다 손으로 고쳐 가며 다듬는 중.","archive.status.next":"다음","archive.status.nextText":"아카이브에서 뽑아낸 짧은 글들, 그다음 책.","archive.quote.text":"“왜 이렇게 얇게? 왜 직화인가? 왜 짐승의 마지막 겹이고 첫 겹이 아닌가?”","archive.quote.cite":"책이 시작되는 세 가지 질문","archive.instagram":"인스타그램의 일상 작업","contact.eyebrow":"문의","contact.title":"고기 이야기, 나눠 봅시다.","contact.lede":"가르칠 세미나, 진행할 마스터클래스, 열 주방, 진열대에 올릴 제품, 혹은 객석에서 아무도 이름을 대지 못하는 부위 — 무엇을 하고 있는지 알려주시면 제가 맞는 사람인지 솔직하게 말씀드리겠습니다.","contact.known.label":"알아 두시면 좋은 것","contact.known.text":"첫 메시지에 담아 주시면 좋습니다: 행사나 프로젝트, 날짜와 도시, 생각하고 계신 관객이나 메뉴, 그리고 작업 사진을 공개해도 되는지.","contact.card.name":"고용재 · Ron","contact.card.role":"정육 명인, 한우 오마카세 셰프, 육류 컨설턴트.","contact.email.label":"이메일","contact.email.small":"가장 빠른 연락 방법입니다.","contact.based.label":"거주","contact.based.value":"대한민국 고양","contact.based.small":"수도권 · GMT+9","contact.working.label":"활동","contact.working.value":"아시아와 미국 전역","contact.working.small":"세미나, 마스터클래스, 주방 오픈, 제품 작업","contact.sessions.label":"진행 언어","contact.sessions.value":"한국어 또는 영어","contact.sessions.small":"통역을 준비할 수 있습니다","contact.youtube.label":"유튜브","contact.youtube.small":"공장과 길 위에서 남긴 현장 노트","contact.writing.label":"집필","contact.writing.value":"육류 인문학 아카이브","contact.writing.small":"집필 중","contact.before.eyebrow":"메시지 전에","contact.before.title":"알아 두시면 좋은 세 가지","contact.q1.title":"출장이 가능한가요?","contact.q1.text":"가능합니다. 지난 2년간 홍콩, 싱가포르, 라오스, 캄보디아, 미국에서 가르치고 컨설팅했고, 일이 부르면 언제든 떠납니다.","contact.q2.title":"돼지고기와 양고기도 다루나요?","contact.q2.text":"그렇습니다. 평판은 소고기에서 왔지만 기술은 돼지 도체로 배웠고, 소·돼지·양고기를 가공하는 공장을 운영하며 샤퀴테리와 건식 숙성 프로그램까지 맡았습니다.","contact.q3.title":"주방뿐 아니라 공장에서도 일할 수 있나요?","contact.q3.text":"제 이력서에서 특이한 부분입니다. HACCP 공장 구축, 표준 작업 절차, 수율과 원가, 가열식 제품 개발, 그리고 그 모든 것을 기록하는 디지털 시스템.","contact.cta.eyebrow":"아니면 여기서부터","contact.cta.title":"먼저 작업을 보세요","contact.cta.text":"네 개 지역, 2년, 그리고 모든 사진의 날짜와 장소를 적어 둔 기록.","contact.cta.b1":"아카이브 열기","contact.cta.b2":"경력 읽기","gallery.count":"{n}장의 사진","lightbox.viewer":"사진 보기","lightbox.viewerTitled":"사진 보기: {title}","lightbox.close":"사진 보기 닫기","lightbox.prev":"이전 사진","lightbox.next":"다음 사진","lightbox.open":"사진 열기","lightbox.openTitled":"사진 열기: {title}"},"ja":{"common.skip":"本文へ移動","common.menu":"メニューを開く","common.brandSub":"文化を読む肉職人","common.brandFull":"Ron Ko · 文化を読む肉職人","common.location":"韓国・高陽","common.langLabel":"言語を選ぶ","common.langMenu":"言語","nav.home":"ホーム","nav.about":"プロフィール","nav.archive":"アーカイブ","nav.contact":"お問い合わせ","meta.index.title":"Ron Ko — 精肉の匠・韓牛おまかせシェフ・肉のコンサルタント","meta.index.desc":"コ・ヨンジェ（Ron）— 18年のキャリアを持つ精肉の匠にしてグリルマスター、韓牛おまかせシェフ、香港・シンガポール・ラオスで韓国韓牛協会の公式講師を務め、現在は韓国のフードテック・スタートアップのCPO。世界各地でコンサルティング、マスタークラス、厨房立ち上げを行っています。","meta.index.ogTitle":"Ron Ko — 文化を読む肉職人","meta.index.ogDesc":"精肉の匠、韓牛おまかせシェフ、グローバルな肉のコンサルタント。シンガポールからボストンまで続いたセミナー、そしてまな板の前で過ごした18年。","meta.about.title":"プロフィール · Ron Ko — 文化を読む肉職人","meta.about.desc":"コ・ヨンジェ（Ron）— 31年の仕事：企業の購買・BPRに10年、金融コンサルティングに5年、そして精肉職人・グリルマスター・韓牛おまかせシェフとして18年。","meta.archive.title":"アーカイブ · Ron Ko — 文化を読む肉職人","meta.archive.desc":"Ron Koの仕事の記録：香港・シンガポール・ラオスの韓牛セミナー、ボストンの韓国焼肉店、精肉の現場、そして休みの日。","meta.contact.title":"お問い合わせ · Ron Ko — 文化を読む肉職人","meta.contact.desc":"韓牛セミナー、精肉マスタークラス、厨房立ち上げ、肉のプログラム、製品コンサルティングのご相談はコ・ヨンジェ（Ron）まで。","home.hero.kicker":"コ・ヨンジェ · Ron","home.hero.title":"精肉の匠。韓牛おまかせシェフ。<em>肉のコンサルタント。</em>","home.hero.lede":"働いてきた31年のうち18年は、包丁とともにありました。韓国で最も厳しい韓牛の名店で精肉部を率い、ソウル・江南（カンナム）の韓牛ダイニング鬱陵でおまかせカウンターを任され、いまはフードテック工場の製品と仕組みをつくっています。今日はシンガポールからボストンまで、パートナーのために教え、切り、焼いています。","home.hero.ctaWork":"仕事を相談する","home.hero.ctaArchive":"アーカイブを見る","home.hero.foot":"韓国・高陽（コヤン）在住 · セミナー、コンサルティング、厨房立ち上げのご相談を承ります","home.hero.alt":"白黒写真。吊るされた牛枝肉に包丁を入れるRon Ko","home.hero.caption":"吊るされた枝肉を解体する。この仕事が何になっても——コースになり、工場になり、ブランドになっても——始まりはいつもここです。","home.m1":"精肉の匠・グリルマスター・ヘッドシェフとしての年数","home.m2":"年のキャリア。うち13年は企業の購買・BPR・金融","home.m3":"鬱陵島の在来チクソ（黒牛）のための渡島","home.m4":"教え、助言し、厨房を開いた国と地域","home.work.eyebrow":"海外プロジェクトと出張","home.work.title":"仕事が連れて行った場所、2025–2026","home.work.intro":"2年で4つの地域。シンガポールの大使館レセプションと屋上グリル、香港での精肉デモンストレーション、ボストンでの韓国焼肉店の立ち上げ、そして東南アジア各地でのセミナーと市場視察。","home.sg.when":"2026 · 10月","home.sg.title":"韓牛、大使館レセプションから屋上グリルまで","home.sg.place":"シンガポール","home.sg.body":"駐シンガポール韓国大使館、Bidfood、現地ディストリビューターとの5日間。最後は屋外マスタークラスで、ゲストはサーロイン一塊が部位ごとに分かれていく様子を見て、そのままグリルで味わいました。","home.sg.f1":"駐シンガポール韓国大使館 — 開天節レセプション、韓牛ブースの運営とサーブ","home.sg.f2":"Bidfood シンガポール — 購買チーム向けショールーム・セッション","home.sg.f3":"ディストリビューター店頭視察 — スモークしたイベリコと鴨","home.sg.f4":"屋外韓牛マスタークラスと夜のグリル・テイスティング","home.sg.link":"シンガポールの写真を見る","home.sg.alt1":"シンガポール、緑のHANWOO KOREAN BEEFバナーの下で開かれた夜のテイスティング、韓牛を焼くシェフたち","home.sg.alt2":"シンガポールの屋上テラスで韓牛サーロインを一塊切るRon Ko","home.sg.alt3":"駐シンガポール韓国大使館のレセプション、HANWOOブースに立つRon Ko","home.hk.when":"2026 · 6月","home.hk.title":"シェフとバイヤーのための精肉デモンストレーション","home.hk.place":"香港","home.hk.body":"韓国韓牛協会のセミナー・プログラムのうち、私が担当する部分です。39の部位を、包丁を手に、メニューに何を載せるかを決めるシェフ・輸入業者・バイヤーの前で解説します。","home.hk.f1":"ステージ上で枝肉ブロックを解体。シェフウェアと手袋姿で","home.hk.f2":"ブロックから部分肉、そして提供カットへ。切り分けながら説明","home.hk.f3":"ホストキッチンとともに盛り付けと試食","home.hk.link":"香港の写真を見る","home.hk.alt1":"黒いシェフジャケットで香港のステージ上、韓牛ブロックの解体を実演するRon Ko","home.hk.alt2":"実演のあと会場に向けて手を振るRon Koとホストシェフ","home.hk.alt3":"香港セミナーの後、主催者とシェフたちと並ぶRon Ko","home.us.when":"2026 · 3月 & 5月","home.us.title":"海外で韓国焼肉の厨房を立ち上げる","home.us.place":"アメリカ・ボストンとニューヨーク","home.us.body":"ボストンではJIN-JEEのチームと、レシピだけでは伝わらないことを扱いました。塊肉のカット、熟成、グリルのマニュアル、厨房の動線、そしてその下にある原価。2026年3月のニューヨークは別の出張で、その写真もここに並べています。","home.us.f1":"JIN-JEE ボストン — トリミング・熟成・グリル技術を厨房チームへ伝授","home.us.f2":"厨房ライン、薪窯、ダイニングの動線を視察","home.us.f3":"2026年3月、ニューヨーク — フィルムとスマホで残した街","home.us.link":"アメリカの写真を見る","home.us.alt1":"ボストンJIN-JEEの厨房ラインと薪窯、フィルム撮影","home.us.alt2":"ボストンでJIN-JEEのチームと囲んだ夕食","home.us.alt3":"ホテルの窓から見たマンハッタンの夜景","home.sea.when":"2025 · 4月 & 10月","home.sea.title":"東南アジアのセミナーと市場視察","home.sea.place":"ラオス · カンボジア · タイ","home.sea.body":"アメリカ出張の前の年。ラオスでは部位を手に韓牛セミナーを行い、2025年4月にはプノンペンとバンコクを巡りました。会場、ショールーム、そしてその間の何でもない路地。","home.sea.f1":"ラオス — 韓牛セミナー、2025年10月","home.sea.f2":"カンボジア — プノンペンの会場とショールーム視察、2025年4月","home.sea.f3":"タイ — バンコク、2025年4月","home.sea.link":"東南アジアの写真を見る","home.sea.alt1":"ラオスのセミナーで韓牛のブロックを示しながら語るRon Ko","home.sea.alt2":"プノンペンのセミナー会場の大型スクリーン","home.sea.alt3":"2025年の出張中に訪れたバンコクのホテルの庭","home.chapters.eyebrow":"代表的なキャリア","home.chapters.title":"18年を、章に分ければ","home.chapters.intro":"日付まで含めた全履歴は<a href=\"about.html\">プロフィール</a>ページにあります。ここに挙げる7つの章が、残りを可能にしました。","home.c1.years":"2018 · 2019","home.c1.title":"Born & Bred — 精肉部長","home.c1.text":"韓国で最も厳しい高級韓牛の名店で、1++枝肉の選定、精密な解体、希少部位と熟成を担当。おまかせの提供中にゲストの前でリブを一塊まるごと骨抜きすることも、その仕事の一部でした。","home.c2.years":"2019 · 2022","home.c2.title":"スンウブラックと韓牛ダイニング鬱陵","home.c2.text":"明洞（ミョンドン）のスンウブラック4フロア店を開店し、最上階のおまかせカウンターを任されました。続いてソウル・江南の韓牛ダイニング鬱陵へ移り、おまかせコースを自ら設計してカウンターを仕切りました。部位を軸にコースを組み、ゲストの目の前で切って出します。","home.c3.years":"2020 · 2022","home.c3.title":"鬱陵島への16回の航海","home.c3.text":"2年、16回の船旅、目的はひとつ。鬱陵島在来の韓牛チクソ（黒牛）です。島の屠畜場で自らブロックを骨抜き・整形し、船で本土へ運んで、ソウル・江南の韓牛ダイニング鬱陵のカウンターへ届けました。間に仲買人はいません。","home.c4.years":"2022 · 2023","home.c4.title":"クァンピョンミート — 取締役","home.c4.text":"ドライエイジング庫2室、シャルキュトリー、ソーセージと生ハム、ナンチュク・マットン（ブランド豚）の立ち上げ、そして外食ブランドや歳暮・贈答セット向けの牛豚供給。","home.c5.years":"2023 · 現在","home.c5.title":"フードテック・スタートアップ — CPO・パートナー取締役","home.c5.text":"低糖・高タンパクの加熱調理済みプルコギライン（100gあたり糖類1.6g、タンパク質最大39g）、HACCP工場、そしてAIとともに一人でつくった工場ERPと現場アプリ。入荷からロット追跡、バッチごとのリアルタイム原価まで457コミット。","home.c6.years":"2024 · 継続中","home.c6.title":"R&Dとテイスティングカウンター","home.c6.text":"仕様書からテイスティングカウンターまで製品を引き上げる仕事——加熱調理済みライン、熟成とシャルキュトリーのプログラム、その背後にあるOEM供給。精肉職人と製品責任者が同じ人間だったと分かるのは、このあたりです。","home.c7.years":"2026 · 執筆中","home.c7.title":"食肉人文学アーカイブを書く","home.c7.text":"食肉の歴史に関する研究7編——家畜化、近代以前の韓国の豚肉、品種改良、そしてこの国がなぜ牛肉を薄く切って直火で焼くのか——と、そこから書いている原稿。","home.wide.caption":"試食・相談ブース — 仕様書がお客様の舌と出会う、この仕事の製品面。","home.wide.meta":"韓国 · 2024.07","home.wide.alt":"食品見本市の試食・相談ブース。カウンターの後ろに立つチーム","home.services.eyebrow":"仕事内容","home.services.title":"三つ、同じ手で","home.s1.title":"精肉と肉のプログラム","home.s1.text":"枝肉の解体、歩留まりと原価、ドライ・ウェットエイジング、シャルキュトリー——そして私が厨房に立っていなくても味がぶれないための標準作業手順まで。","home.s1.i1":"枝肉・ブロックの解体","home.s1.i2":"熟成、シャルキュトリー、塩漬け","home.s1.i3":"歩留まり・原価・メニュー構成","home.s2.title":"韓牛マスタークラスとセミナー","home.s2.text":"シェフ、輸入業者、ディストリビューター、見本市のために、包丁を手に部位を解説します。韓国語で、英語で、あるいは通訳を介して——韓国韓牛協会と海外で行っているのと同じプログラムです。","home.s2.i1":"B2Bセミナーと見本市","home.s2.i2":"ライブ精肉デモンストレーション","home.s2.i3":"シェフ・バイヤー研修","home.s3.title":"外食・製品コンサルティング","home.s3.text":"店舗立ち上げ、厨房動線、グリルマニュアル、原価構造——そして製造側では、加熱調理済み製品の開発、HACCP工程、それを支えるデジタルシステム。","home.s3.i1":"厨房・サービス設計","home.s3.i2":"RTH／OEM製品開発","home.s3.i3":"HACCP工場の構築とERP","home.quote.text":"「ある民族の歴史は、獣をどう切るかに書かれている。」","home.quote.cite":"食肉人文学アーカイブ · 執筆中","home.closing.p1":"最後につくりたいのは、レストランでも製品でもありません。韓国人がなぜ牛肉を薄く切り、直火で焼き、獣を最後の一層まで食べるのか——その本です。民族的な誇りではなく、まな板と屠畜場、そして史料から書いています。","home.closing.p2":"研究7編は完成しています。品種の歴史、近代以前の韓国の豚肉、「和牛のルーツ」「サムギョプサルの輸出」という語りの事実関係、古い記録に残る牛の色、そして中国・ヨーロッパ・韓国がそれぞれ獣をどう料理に変えたか。いま原稿を書いています。","home.closing.cta":"プロジェクトについて読む","home.cta.eyebrow":"お問い合わせ","home.cta.title":"肉の話をしませんか。","home.cta.text":"教えるセミナー、開く厨房、棚に並べる製品、あるいはその場の誰も名前を知らない部位——何に取り組んでいるか、お聞かせください。","home.cta.more":"ほかの連絡方法","about.eyebrow":"プロフィール","about.title":"31年、包丁は二番目でした。","about.portraitAlt":"シンガポールの屋外で韓牛サーロインを一塊切るRon Ko、背後にシンガポールのスカイライン","about.portraitCaption":"2026年10月、シンガポール。屋外マスタークラスでサーロインを一塊、切り分ける。","about.p1":"働き始めて最初の13年は、仕組みの中にいました。1995年から上場建設会社の購買部で鉄筋、生コン、厚板、下請け入札を扱い、続いて全社BPRチームで全部署の業務を分解し、設計し直してコンピュータに載せました。2003年から2007年は金融商品を販売。知らない人の前に座り、難しいことを平易な言葉で説明する訓練になった時期です。","about.p2":"2007年10月、手で技術を覚えるために精肉店の扉を開けました。豚枝肉で18か月、牛肉で1年。それから工場、プラント、そしてダイニングへ。高級韓牛の名店、ソウル・江南の韓牛ダイニング鬱陵のおまかせカウンター、チクソのために16回通った鬱陵島の屠畜場、シャルキュトリーのプログラム、そして製品統括を務めるフードテック・スタートアップ。","about.p3":"商売を覚えたシェフでも、食べることが好きな実業家でもありません。先に企業の仕組みの中で10年を過ごした精肉職人——その組み合わせが私の仕事です。教えられ、原価を計算でき、文書に残して繰り返せる技術。","about.stat1":"年のキャリア","about.stat2":"年を包丁とともに","about.stat3":"年は企業の仕組みの中で先に","about.timeline.eyebrow":"年表","about.timeline.title":"順番に並べたキャリア","about.timeline.intro":"ここにある日付は、実際に始めた月と終えた月です。空いている期間は、まっすぐな道ではなかったからです。","about.era1":"2023 — 現在","about.era2":"2013 — 2023","about.era3":"2007 — 2012","about.era4":"1995 — 2007","about.r1.years":"2023.12 – 現在","about.r1.role":"CPO・パートナー取締役、フードテック・スタートアップ","about.r1.small":"低糖・高タンパクの加熱調理済みプルコギライン、HACCP工場、AIとともに一人でつくった工場ERP・現場アプリ（457コミット）。","about.r2.years":"2026 – 現在","about.r2.role":"食肉人文学アーカイブの執筆","about.r2.small":"研究7編を完了、原稿を執筆中。","about.r3.years":"2022.06 – 2023.11","about.r3.role":"クァンピョンミート 取締役","about.r3.small":"ドライエイジング庫2室、シャルキュトリー・ソーセージ・生ハム、ナンチュク・マットンの立ち上げ、外食ブランドと歳暮・贈答セットへの供給。","about.r4.years":"2020.05 – 2022.06","about.r4.role":"韓牛ダイニング鬱陵 支店長","about.r4.small":"ソウル・江南のカウンターでおまかせコースを企画・進行。在来チクソのために鬱陵島へ16回渡島し、屠畜場で自ら骨抜き、船で本土へ運びました。","about.r5.years":"2019.08 – 2020.05","about.r5.role":"スンウブラック明洞 支店長","about.r5.small":"4フロアの店舗を開店し、最上階のプレミアムおまかせカウンターを運営。","about.r6.years":"2018.09 – 2019.08","about.r6.role":"Born & Bred 精肉部長","about.r6.small":"韓国のプレミアム韓牛店で、1++の選定、精密な枝肉解体、希少部位と熟成。","about.r7.years":"2013 – 2018","about.r7.role":"独立厨房の時代","about.r7.small":"韓国焼肉専門店の精肉部長（2014）、坡州（パジュ）のセルフ焼肉店運営（2015）、韓牛ダイニングの精肉部長兼グリルシェフ（2016–17）。","about.r8.years":"2012.03 – 2012.10","about.r8.role":"オセンシティックミート 工場長","about.r8.small":"パティ、手づくりソーセージ、ステーキ — 一次・二次加工、工程と衛生。","about.r9.years":"2010.04 – 2011.12","about.r9.role":"ジエム畜産 生産チーム長","about.r9.small":"1日4〜6頭の枝肉、専用工場での精密解体と二次加工。","about.r10.years":"2009.03 – 2010.03","about.r10.role":"アウリム韓牛村 精肉チーム長","about.r10.small":"精肉食堂向けの韓牛解体、近隣工業団地向けB2B歳暮・贈答セット。","about.r11.years":"2007.10 – 2009.03","about.r11.role":"キョハ精肉マート 精肉部","about.r11.small":"始まりの場所：豚枝肉で18か月、牛肉で1年。","about.r12.years":"2003.05 – 2007.09","about.r12.role":"ING生命 ファイナンシャルコンサルタント","about.r12.small":"個人・法人のファイナンシャルプランニング。","about.r13.years":"1995.03 – 2003.04","about.r13.role":"コリョ開発（大林グループ）購買・BPR","about.r13.small":"鉄筋・生コン・厚板など大量資材の購買、続いて全社業務プロセスの再設計とその後のERP。","about.note":"学歴：明知（ミョンジ）大学 貿易学科（1989–1994）。<a href=\"archive.html\">アーカイブ</a>に写真が残る出張のほか、香港・シンガポール・ラオスで韓国韓牛協会の公式韓牛講師を、2026年にはボストンでK-BBQ厨房のコンサルティングを行いました。","about.off.eyebrow":"仕事の外で","about.off.title":"趣味と旅","about.off.intro":"まな板の前に立っていない日を満たすもの。道、コース、フィルム、そして家族。","about.cycling.label":"サイクリング","about.cycling.text":"主にロードバイク。アーカイブの古い写真は弥矢嶺（ミシリョン）峠の頂上で撮ったもので、いまもその登りを一年の物差しにしています。","about.cycling.alt":"ライド前にヘルメットをかぶったRon Ko","about.golf.label":"ゴルフ","about.golf.text":"カレンダーが許すときに。調子の悪い日でも外で4時間過ごせる、唯一の遊びです。","about.golf.alt":"ゴルフコースに立つRon Ko","about.film.label":"フィルム写真","about.film.text":"古いフィルムカメラは毎回の旅に同行します。このサイトのボストンとニューヨークの写真も何枚かはそのカメラで撮ったものです。","about.film.alt":"古いフィルムカメラを手にしたRon Ko","about.japan.label":"旅 · 日本 2025","about.japan.text":"家族と名古屋へ。午後じゅう居たかった包丁店、そして松阪牛と但馬牛の品種史の展示。","about.japan.alt":"名古屋の包丁店の店内","about.extra.p1":"コーヒーはドリップ。何度も戻ってくるのはケニアAAとエチオピアのウォッシュト——厨房で何より先に湯温を論じる人間です。","about.extra.p2":"残りの時間は<a href=\"archive.html#writing\">食肉人文学アーカイブ</a>のための読書に。古い記録、品種登録簿、そして村が何を食べたかを書き留めた人たちの文章。","about.quote.text":"「包丁は道具です。ゲストが覚えている部位を知ることが、この仕事です。」","about.quote.cite":"Ron Ko","about.cta.contact":"連絡する","about.cta.archive":"アーカイブを見る","archive.eyebrow":"アーカイブ","archive.title":"順番に残した記録","archive.lede":"セミナー、マスタークラス、厨房、工場、ときどき休日。すべての写真には撮った日と場所があります。日付が分からない写真には日付を付けていません。","archive.filterLabel":"アーカイブを絞り込む","filter.all":"すべて","filter.trips":"海外出張・セミナー","filter.craft":"精肉・ダイニング・R&D","filter.travel":"旅・趣味","archive.empty":"写真を準備中です — しばらくしてからご覧ください。","archive.writing.eyebrow":"執筆 · 食肉人文学アーカイブ","archive.writing.title":"肉を、文字にする","archive.writing.p1":"食肉の歴史と文化をめぐる長期プロジェクト。牛と豚の家畜化から、韓国の料理人がなぜ牛肉を薄く切って直火で焼き、獣を最後の一層まで食べるのかまで。","archive.writing.p2":"主張は、どの国の牛肉が一番おいしいか、ではありません。ある民族が獣を切り、焼き、食べるやり方にはその歴史が宿っており、その記録は繰り返し語られるのではなく、近く読まれるべきだということです。","archive.status.research":"研究","archive.status.researchText":"研究7編を完成、テーマ別に整理——品種と在来牛、近代以前の韓国の豚肉、古い記録、「和牛のルーツ」「サムギョプサルの輸出」の語りの史料照合、精肉と調理法。","archive.status.manuscript":"原稿","archive.status.manuscriptText":"序文とプロローグの草稿を書き、章ごとに手で直しながら整えています。","archive.status.next":"次","archive.status.nextText":"アーカイブから生まれた短い文章、そして本。","archive.quote.text":"「なぜこんなに薄く。なぜ直火で。なぜ獣の最初の一層ではなく、最後の一層なのか。」","archive.quote.cite":"本が始まる三つの問い","archive.instagram":"インスタグラムの日々の仕事","contact.eyebrow":"お問い合わせ","contact.title":"肉の話をしましょう。","contact.lede":"教えるセミナー、行うマスタークラス、開く厨房、棚に並べる製品、あるいはその場の誰も名前を知らない部位——何に取り組んでいるかを教えていただければ、私が適任かどうかを正直にお伝えします。","contact.known.label":"知っておいていただきたいこと","contact.known.text":"最初のメッセージに：行事やプロジェクト、日付と都市、想定している参加者やメニュー、そして仕事の写真を公開してよいかどうか。","contact.card.name":"コ・ヨンジェ · Ron","contact.card.role":"精肉の匠、韓牛おまかせシェフ、肉のコンサルタント。","contact.email.label":"メール","contact.email.small":"いちばん確実な連絡方法です。","contact.based.label":"拠点","contact.based.value":"韓国・高陽（コヤン）","contact.based.small":"首都圏 · GMT+9","contact.working.label":"活動","contact.working.value":"アジアとアメリカ各地","contact.working.small":"セミナー、マスタークラス、厨房立ち上げ、製品開発","contact.sessions.label":"対応言語","contact.sessions.value":"韓国語または英語","contact.sessions.small":"通訳の手配も可能です","contact.youtube.label":"ユーチューブ","contact.youtube.small":"工場と道の上での現場ノート","contact.writing.label":"執筆","contact.writing.value":"食肉人文学アーカイブ","contact.writing.small":"執筆中","contact.before.eyebrow":"メッセージの前に","contact.before.title":"知っておいていただきたい三つ","contact.q1.title":"出張できますか。","contact.q1.text":"はい。この2年で香港、シンガポール、ラオス、カンボジア、アメリカで教え、助言してきました。仕事が呼べばすぐに動きます。","contact.q2.title":"豚肉やラムも扱いますか。","contact.q2.text":"はい。評判は牛肉で立ててきましたが、技術は豚枝肉で覚えました。牛・豚・ラムを加工する工場を運営し、シャルキュトリーやドライエイジングのプログラムも担当しています。","contact.q3.title":"厨房だけでなく工場でも働けますか。","contact.q3.text":"そこが私の経歴の変わったところです。HACCP工場の構築、標準作業手順、歩留まりと原価、加熱調理済み製品の開発、そしてそれらすべてを記録するデジタルシステム。","contact.cta.eyebrow":"あるいはここから","contact.cta.title":"まず仕事を見てください","contact.cta.text":"4つの地域、2年、そしてすべての写真の日付と場所を記した記録。","contact.cta.b1":"アーカイブを開く","contact.cta.b2":"キャリアを読む","gallery.count":"{n}枚の写真","lightbox.viewer":"写真ビューア","lightbox.viewerTitled":"写真ビューア：{title}","lightbox.close":"写真ビューアを閉じる","lightbox.prev":"前の写真","lightbox.next":"次の写真","lightbox.open":"写真を開く","lightbox.openTitled":"写真を開く：{title}"},"zh":{"common.skip":"跳到正文","common.menu":"打开菜单","common.brandSub":"读懂文化的肉品匠人","common.brandFull":"Ron Ko · 读懂文化的肉品匠人","common.location":"韩国 高阳","common.langLabel":"选择语言","common.langMenu":"语言","nav.home":"首页","nav.about":"关于","nav.archive":"影像档案","nav.contact":"联系","meta.index.title":"Ron Ko — 肉品匠人 · 韩牛 Omakase 主厨 · 肉类顾问","meta.index.desc":"Yongjae Ko（Ron）——十八年经验的肉品匠人与烤肉大师、韩牛 Omakase 主厨、在香港、新加坡和老挝授课的韩牛协会官方讲师，以及一家韩国食品科技初创公司的 CPO。在全球提供咨询、大师班与厨房开业服务。","meta.index.ogTitle":"Ron Ko — 读懂文化的肉品匠人","meta.index.ogDesc":"肉品匠人、韩牛 Omakase 主厨、全球肉类顾问。从新加坡到波士顿的讲座，以及在案板前度过的十八年。","meta.about.title":"关于 · Ron Ko — 读懂文化的肉品匠人","meta.about.desc":"Yongjae Ko（Ron）——三十一年的工作：十年企业采购与流程再造，五年金融咨询，以及十八年作为肉品匠人、烤肉大师与韩牛 Omakase 主厨。","meta.archive.title":"影像档案 · Ron Ko — 读懂文化的肉品匠人","meta.archive.desc":"Ron Ko 的工作记录：香港、新加坡与老挝的韩牛讲座，波士顿的韩式烤肉店，分割现场，以及休息的日子。","meta.contact.title":"联系 · Ron Ko — 读懂文化的肉品匠人","meta.contact.desc":"韩牛讲座、分割大师班、厨房开业、肉类项目与产品咨询——请联系 Yongjae Ko（Ron）。","home.hero.kicker":"Yongjae Ko · Ron","home.hero.title":"肉品匠人。韩牛 Omakase 主厨。<em>肉类顾问。</em>","home.hero.lede":"工作的三十一年里，有十八年手握刀具——在韩国最讲究的韩牛餐厅主管肉品部，在首尔江南的韩牛餐饮“郁陵”执掌 Omakase 吧台，如今在为一家食品科技工厂打造产品与系统。从新加坡到波士顿，我为合作伙伴授课、分割、烧烤。","home.hero.ctaWork":"与我合作","home.hero.ctaArchive":"查看档案","home.hero.foot":"现居韩国高阳 · 可承接讲座、咨询与厨房开业","home.hero.alt":"黑白照片：Ron Ko 在悬挂的牛胴体前下刀","home.hero.caption":"分割悬挂的胴体。无论这份工作后来变成什么——一道菜、一座工厂、一个品牌——它都从这里开始。","home.m1":"年，作为分割师、烤肉大师与主厨","home.m2":"年职业生涯，其中十三年在企业采购、流程再造与金融","home.m3":"次往返郁陵岛，为本土赤牛（Chikso）","home.m4":"个国家与地区授课、咨询或开设厨房","home.work.eyebrow":"全球项目与出差","home.work.title":"工作带我去过的地方，2025–2026","home.work.intro":"两年，四个地区：新加坡的大使馆招待会与屋顶烧烤，香港的分割演示，波士顿的韩式烤肉店开业，以及东南亚各地的讲座与市场走访。","home.sg.when":"2026 · 10月","home.sg.title":"韩牛，从大使馆招待会到屋顶烧烤","home.sg.place":"新加坡","home.sg.body":"与韩国驻新加坡大使馆、Bidfood 以及当地经销商合作的五天。最后是一场户外大师班：客人看着整块西冷被分成各个部位，然后直接在烤炉上食用。","home.sg.f1":"韩国驻新加坡大使馆——开天节招待会，韩牛展台与服务","home.sg.f2":"Bidfood 新加坡——面向采购团队的展厅课程","home.sg.f3":"经销商货架考察——烟熏伊比利亚猪肉与鸭肉","home.sg.f4":"户外韩牛大师班与夜间烧烤品鉴","home.sg.link":"查看新加坡照片","home.sg.alt1":"新加坡绿色 HANWOO KOREAN BEEF 横幅下的夜间品鉴会，正在烤韩牛的主厨们","home.sg.alt2":"Ron Ko 在新加坡屋顶露台分割整块韩牛西冷","home.sg.alt3":"Ron Ko 站在韩国驻新加坡大使馆招待会的 HANWOO 展台前","home.hk.when":"2026 · 6月","home.hk.title":"面向主厨与买家的分割演示","home.hk.place":"香港","home.hk.body":"韩牛协会讲座项目中由我负责的部分：手持刀具，向决定菜单内容的主厨、进口商与买家讲解三十九个部位。","home.hk.f1":"在台上分解整块部位，身穿厨师服、戴手套","home.hk.f2":"从大分割到小分割，再到出品切块，边切边讲","home.hk.f3":"与主办厨房一起摆盘与品鉴","home.hk.link":"查看香港照片","home.hk.alt1":"身穿黑色厨师服的 Ron Ko 在香港现场演示韩牛大部位分割","home.hk.alt2":"演示结束后，Ron Ko 与主办主厨向会场挥手","home.hk.alt3":"香港讲座结束后，Ron Ko 与主办方和主厨们合影","home.us.when":"2026 · 3月 & 5月","home.us.title":"在海外开设韩式烤肉厨房","home.us.place":"美国 波士顿与纽约","home.us.body":"在波士顿，我与 JIN-JEE 团队一起处理菜谱带不走的东西：整块肉的切割、熟成、烧烤手册、厨房动线，以及这一切下面的成本。2026年3月的纽约是另一次行程，那里的照片也放在这里。","home.us.f1":"JIN-JEE 波士顿——向厨房团队传授修整、熟成与烧烤技法","home.us.f2":"考察厨房动线、柴火炉与餐厅动线","home.us.f3":"2026年3月，纽约——用胶片和手机记录的城市","home.us.link":"查看美国照片","home.us.alt1":"波士顿 JIN-JEE 的厨房动线与柴火炉，胶片拍摄","home.us.alt2":"在波士顿与 JIN-JEE 团队共进晚餐","home.us.alt3":"从酒店窗户望见的曼哈顿夜景","home.sea.when":"2025 · 4月 & 10月","home.sea.title":"东南亚的讲座与市场走访","home.sea.place":"老挝 · 柬埔寨 · 泰国","home.sea.body":"美国之行前的一年：在老挝手拿部位做韩牛讲座；2025年4月走访金边与曼谷——会场、展厅，以及它们之间普通的街道。","home.sea.f1":"老挝——韩牛讲座，2025年10月","home.sea.f2":"柬埔寨——金边会场与展厅走访，2025年4月","home.sea.f3":"泰国——曼谷，2025年4月","home.sea.link":"查看东南亚照片","home.sea.alt1":"Ron Ko 在老挝讲座上展示韩牛大部位","home.sea.alt2":"金边讲座会场的大屏幕","home.sea.alt3":"2025年行程中到访的曼谷酒店花园","home.chapters.eyebrow":"代表经历","home.chapters.title":"十八年，分成几章","home.chapters.intro":"带日期的完整履历在<a href=\"about.html\">关于</a>页面。下面这七段，让其余的一切成为可能。","home.c1.years":"2018 · 2019","home.c1.title":"Born & Bred——肉品部主管","home.c1.text":"在韩国最讲究的高端韩牛餐厅负责 1++ 胴体挑选、精确分割、特殊部位与熟成——包括在 Omakase 席间于客人面前整块剔骨。","home.c2.years":"2019 · 2022","home.c2.title":"Soonwoo Black 与韩牛餐饮郁陵","home.c2.text":"开设 Soonwoo Black 明洞四层店并主管顶层的 Omakase 吧台，随后转到首尔江南的韩牛餐饮“郁陵”，亲自设计并主理 Omakase 套餐：以部位为核心的套餐，在客人面前现切。","home.c3.years":"2020 · 2022","home.c3.title":"十六次前往郁陵岛","home.c3.text":"两年，十六次渡海，一个目的：郁陵岛土生的韩牛“赤牛”（Chikso）。我在岛上屠宰场亲手剔骨修整，再用船运到内陆，送到首尔江南韩牛餐饮“郁陵”的吧台。中间没有中间商。","home.c4.years":"2022 · 2023","home.c4.title":"广平肉业——董事","home.c4.text":"两间干式熟成室、风干肉品、香肠与生火腿、Nangchuk Matdon 猪肉上市，以及向餐饮品牌与节日礼盒供应牛肉与猪肉。","home.c5.years":"2023 · 至今","home.c5.title":"食品科技初创公司——CPO 兼合伙人董事","home.c5.text":"低糖高蛋白即热烤肉（Bulgogi）产品线——每 100 克糖 1.6 克、蛋白质最高 39 克——以及 HACCP 工厂，还有我借助 AI 独自搭建的工厂 ERP 与现场 App：457 次提交，从收货、批次追溯到每批实时成本。","home.c6.years":"2024 · 持续中","home.c6.title":"研发与品鉴台","home.c6.text":"把产品从规格书推到品鉴台——即热产品线、熟成与风干肉品项目，以及背后的 OEM 供应。分割师与产品负责人其实是同一个人，这里最能说明。","home.c7.years":"2026 · 撰写中","home.c7.title":"撰写肉类人文档案","home.c7.text":"七篇关于肉类历史的研究——驯化、近代以前的韩国猪肉、品种改良，以及这个国家为何把牛肉切得薄、架在明火上烤——以及正在据此撰写的书稿。","home.wide.caption":"品鉴与咨询展台——规格书与客人口味相遇的地方，这份工作的产品一侧。","home.wide.meta":"韩国 · 2024.07","home.wide.alt":"食品展会的产品品鉴与咨询展台，柜台后的团队","home.services.eyebrow":"我做的事","home.services.title":"三件事，同一双手","home.s1.title":"分割与肉类项目","home.s1.text":"胴体分割、出成率与成本、干式与湿式熟成、风干肉品——以及让我不在厨房时出品依然稳定的标准作业流程。","home.s1.i1":"胴体与大部位分割","home.s1.i2":"熟成、风干肉品、腌制","home.s1.i3":"出成率、成本与菜单结构","home.s2.title":"韩牛大师班与讲座","home.s2.text":"面向主厨、进口商、经销商与展会：手持刀具讲解部位，用韩语、英语或通过翻译——与我在海外为韩牛协会讲授的同一套课程。","home.s2.i1":"B2B 讲座与展会","home.s2.i2":"现场分割演示","home.s2.i3":"主厨与买家培训","home.s3.title":"餐饮与产品咨询","home.s3.text":"餐厅开业、厨房动线、烧烤手册、成本结构——在制造端则是即热产品开发、HACCP 工艺以及背后的数字系统。","home.s3.i1":"厨房与服务设计","home.s3.i2":"即热（RTH）／OEM 产品开发","home.s3.i3":"HACCP 工厂搭建与 ERP","home.quote.text":"“一个民族的历史，写在它如何切割一头牲畜里。”","home.quote.cite":"肉类人文档案 · 撰写中","home.closing.p1":"我最后想做的，不是餐厅，也不是产品。而是一本关于韩国人为什么把牛肉切薄、架在明火上烤、把一头牲畜吃到最后一层的书。它不写民族自豪感，而是从案板、屠宰场和史料写起。","home.closing.p2":"七篇研究已经完成：品种的历史、近代以前的韩国猪肉、“和牛起源”与“五花肉出口”说法的事实核对、旧文献里牛的毛色，以及中国、欧洲、韩国各自如何把一头牲畜变成一种饮食。书稿正在写。","home.closing.cta":"读读这个项目","home.cta.eyebrow":"联系","home.cta.title":"聊聊肉？","home.cta.text":"要讲授的讲座、要开业的厨房、要上架的产品，或者现场没人叫得出名字的部位——告诉我你在做什么，我会回信。","home.cta.more":"更多联系方式","about.eyebrow":"关于","about.title":"三十一年，刀是第二位。","about.portraitAlt":"Ron Ko 在新加坡户外分割整块韩牛西冷，背景是新加坡天际线","about.portraitCaption":"2026年10月，新加坡。在户外大师班上分割整块西冷。","about.p1":"工作的最初十三年，我在系统里度过。1995年起，我在一家上市建设公司的采购部处理钢筋、商品混凝土、钢板与分包招标，随后进入全公司流程再造团队，把每个部门的流程拆开、重新设计并搬到电脑上。2003年到2007年，我销售金融产品——那段经历教会我坐在陌生人面前，用平常的话解释一件难事。","about.p2":"2007年10月，为了用手学一门手艺，我走进了一家肉铺。在猪胴体上十八个月，牛肉一年。然后是工厂、车间，再回到餐厅：高端韩牛餐厅、首尔江南韩牛餐饮“郁陵”的 Omakase 吧台、为赤牛十六次往返的郁陵岛屠宰场、风干肉品项目，以及现在由我统管产品的食品科技初创公司。","about.p3":"我不是顺手做生意的厨师，也不是喜欢美食的生意人。我是先在企业系统里待了十年的分割师，而这个组合就是我的工作：一门能教、能算成本、能写下来重复的手艺。","about.stat1":"年职业生涯","about.stat2":"年与刀为伴","about.stat3":"年先在企业系统里","about.timeline.eyebrow":"年表","about.timeline.title":"按顺序排列的履历","about.timeline.intro":"这里的每个日期，都是我实际开始与结束的月份。中间空出来的时间，因为路并不直。","about.era1":"2023 — 至今","about.era2":"2013 — 2023","about.era3":"2007 — 2012","about.era4":"1995 — 2007","about.r1.years":"2023.12 – 至今","about.r1.role":"CPO 兼合伙人董事，食品科技初创公司","about.r1.small":"低糖高蛋白即热烤肉产品线；HACCP 工厂；借助 AI 独自搭建的工厂 ERP 与现场 App（457 次提交）。","about.r2.years":"2026 – 至今","about.r2.role":"撰写肉类人文档案","about.r2.small":"七篇研究已完成，书稿撰写中。","about.r3.years":"2022.06 – 2023.11","about.r3.role":"广平肉业 董事","about.r3.small":"两间干式熟成室，风干肉品、香肠与生火腿；Nangchuk Matdon 猪肉上市；供应餐饮品牌与节日礼盒。","about.r4.years":"2020.05 – 2022.06","about.r4.role":"韩牛餐饮郁陵 店长","about.r4.small":"在首尔江南的吧台企划并主理 Omakase 套餐；为本土赤牛十六次登岛，在屠宰场亲手剔骨，再用船运往内陆。","about.r5.years":"2019.08 – 2020.05","about.r5.role":"Soonwoo Black 明洞 店长","about.r5.small":"开设四层门店，经营顶层的精品 Omakase 吧台。","about.r6.years":"2018.09 – 2019.08","about.r6.role":"Born & Bred 肉品部主管","about.r6.small":"在韩国精品韩牛餐厅负责 1++ 挑选、精确胴体分割、特殊部位与熟成。","about.r7.years":"2013 – 2018","about.r7.role":"独立厨房时期","about.r7.small":"韩式烤肉专门店肉品主管（2014）；经营坡州自助烤肉店（2015）；韩牛餐厅肉品主管兼烧烤主厨（2016–17）。","about.r8.years":"2012.03 – 2012.10","about.r8.role":"奥森蒂克肉业 厂长","about.r8.small":"肉饼、手工香肠与牛排——一次与二次加工、工艺与卫生。","about.r9.years":"2010.04 – 2011.12","about.r9.role":"GM 畜产 生产组长","about.r9.small":"每天四到六头胴体，在专用工场进行精确分割与二次加工。","about.r10.years":"2009.03 – 2010.03","about.r10.role":"Aurim 韩牛村 肉品组长","about.r10.small":"为烤肉餐厅分割韩牛；为附近产业园提供 B2B 节日礼盒。","about.r11.years":"2007.10 – 2009.03","about.r11.role":"交河肉品市场 肉品部","about.r11.small":"开始的地方：猪胴体十八个月，牛肉一年。","about.r12.years":"2003.05 – 2007.09","about.r12.role":"ING 生命 财务顾问","about.r12.small":"个人与企业财务规划。","about.r13.years":"1995.03 – 2003.04","about.r13.role":"高丽开发（大林集团）采购与流程再造","about.r13.small":"钢筋、混凝土、钢板等大宗原材料采购，随后是全公司流程重新设计与随之而来的 ERP。","about.note":"学历：明知大学 贸易学（1989–1994）。除了<a href=\"archive.html\">档案</a>里留下照片的行程之外，我还在香港、新加坡与老挝担任韩牛协会官方韩牛讲师，并于 2026 年在波士顿做过 K-BBQ 厨房咨询。","about.off.eyebrow":"工作之外","about.off.title":"兴趣与旅行","about.off.intro":"不在案板前的日子靠什么填满：路、球场、胶片，还有家人。","about.cycling.label":"骑行","about.cycling.text":"主要是公路车。档案里那张旧照片拍于弥矢岭山顶，至今我仍把那段爬坡当作一年的标尺。","about.cycling.alt":"骑行前戴着头盔的 Ron Ko","about.golf.label":"高尔夫","about.golf.text":"日程允许时就去。这是一项即使打得糟糕，也能在户外待上四小时的运动。","about.golf.alt":"站在高尔夫球场上的 Ron Ko","about.film.label":"胶片摄影","about.film.text":"一台老胶片相机每次都跟着上路。这个网站上波士顿和纽约的照片，有几张就是它拍的。","about.film.alt":"手持老胶片相机的 Ron Ko","about.japan.label":"旅行 · 日本 2025","about.japan.text":"与家人去名古屋：一家我想待一下午的刀具店，还有松阪牛与但马牛的品种历史展。","about.japan.alt":"名古屋一家刀具店的店内","about.extra.p1":"咖啡是手冲。反复回到的两袋是肯尼亚 AA 和埃塞俄比亚水洗——在厨房里，我会先为水温争论，再谈别的。","about.extra.p2":"其余的空闲时间用来为<a href=\"archive.html#writing\">肉类人文档案</a>读书：旧文献、品种登记册，以及那些记录一个村庄吃什么的人写下的文字。","about.quote.text":"“刀是工具。知道客人会记住哪个部位，才是这门手艺。”","about.quote.cite":"Ron Ko","about.cta.contact":"联系我","about.cta.archive":"查看档案","archive.eyebrow":"影像档案","archive.title":"按顺序保存的记录","archive.lede":"讲座、大师班、厨房、工厂，偶尔还有休息日。每张照片都带着拍摄的日期与地点；不知道日期的，就不写日期。","archive.filterLabel":"筛选档案","filter.all":"全部","filter.trips":"海外行程与讲座","filter.craft":"分割、餐饮与研发","filter.travel":"旅行与兴趣","archive.empty":"照片正在整理中——请稍后再看。","archive.writing.eyebrow":"写作 · 肉类人文档案","archive.writing.title":"把肉写成文字","archive.writing.p1":"一个关于肉类历史与文化的长期项目——从牛与猪的驯化，到这个国家的厨师为什么把牛肉切薄、架在明火上烤，把一头牲畜吃到最后一层。","archive.writing.p2":"我想说的不是哪个国家的牛肉最好。而是一个民族切割、烧烤、食用一头牲畜的方式里带着它的历史，这份记录值得被仔细阅读，而不是被反复转述。","archive.status.research":"研究","archive.status.researchText":"七篇研究已完成，按主题整理——品种与本土畜种、近代以前的韩国猪肉、旧文献、“和牛起源”与“五花肉出口”说法的史料核对、分割与烹调方法。","archive.status.manuscript":"书稿","archive.status.manuscriptText":"导言与序章的初稿已完成，正一章一章地手改。","archive.status.next":"下一步","archive.status.nextText":"从档案里长出的短文，然后是一本书。","archive.quote.text":"“为什么这么薄？为什么用明火？为什么是牲畜的最后一层，而不是第一层？”","archive.quote.cite":"这本书开始于三个问题","archive.instagram":"Instagram 上的日常","contact.eyebrow":"联系","contact.title":"聊聊肉吧。","contact.lede":"要讲授的讲座、要主持的大师班、要开业的厨房、要上架的产品，或者现场没人叫得出名字的部位——告诉我你在做什么，我会坦白说自己是合适的人。","contact.known.label":"可以提前告知","contact.known.text":"第一条消息里写明这些会很有帮助：活动或项目、日期与城市、预期的听众或菜单，以及工作照片是否可以公开发布。","contact.card.name":"Yongjae Ko · Ron","contact.card.role":"肉品匠人、韩牛 Omakase 主厨、肉类顾问。","contact.email.label":"邮件","contact.email.small":"最可靠的联络方式。","contact.based.label":"所在","contact.based.value":"韩国 高阳","contact.based.small":"首都圈 · GMT+9","contact.working.label":"活动范围","contact.working.value":"亚洲与美国各地","contact.working.small":"讲座、大师班、厨房开业、产品开发","contact.sessions.label":"使用语言","contact.sessions.value":"韩语或英语","contact.sessions.small":"可以安排翻译","contact.youtube.label":"YouTube","contact.youtube.small":"来自工厂与路上的现场笔记","contact.writing.label":"写作","contact.writing.value":"肉类人文档案","contact.writing.small":"撰写中","contact.before.eyebrow":"来信之前","contact.before.title":"值得先知道的三件事","contact.q1.title":"可以出差吗？","contact.q1.text":"可以。过去两年我在香港、新加坡、老挝、柬埔寨与美国授课和咨询，工作需要时随时出发。","contact.q2.title":"也做猪肉和羊肉吗？","contact.q2.text":"做。名声来自牛肉，但我的手艺是在猪胴体上学的；我经营过加工牛、猪、羊肉的工厂，也负责过风干肉品与干式熟成项目。","contact.q3.title":"除了厨房，也能在工厂工作吗？","contact.q3.text":"这是我履历里比较特别的部分：HACCP 工厂搭建、标准作业流程、出成率与成本、即热产品开发，以及记录这一切的数字系统。","contact.cta.eyebrow":"或者从这里开始","contact.cta.title":"先看看工作","contact.cta.text":"四个地区，两年，一份写明每张照片日期与地点的记录。","contact.cta.b1":"打开档案","contact.cta.b2":"读读履历","gallery.count":"{n} 张照片","lightbox.viewer":"照片查看器","lightbox.viewerTitled":"照片查看器：{title}","lightbox.close":"关闭照片查看器","lightbox.prev":"上一张","lightbox.next":"下一张","lightbox.open":"打开照片","lightbox.openTitled":"打开照片：{title}"},"es":{"common.skip":"Ir al contenido","common.menu":"Abrir menú","common.brandSub":"Carnicero cultural","common.brandFull":"Ron Ko · Carnicero cultural","common.location":"Goyang, Corea","common.langLabel":"Elegir idioma","common.langMenu":"Idioma","nav.home":"Inicio","nav.about":"Perfil","nav.archive":"Archivo","nav.contact":"Contacto","meta.index.title":"Ron Ko — Maestro carnicero, chef de omakase de Hanwoo y consultor de carne","meta.index.desc":"Yongjae Ko (Ron): maestro carnicero y parrillero con dieciocho años de oficio, chef de omakase de Hanwoo, instructor oficial de la Korea Beef Association en Hong Kong, Singapur y Laos, y CPO de una startup coreana de food-tech. Consultoría, clases magistrales y aperturas de cocina en todo el mundo.","meta.index.ogTitle":"Ron Ko — Carnicero cultural","meta.index.ogDesc":"Maestro carnicero, chef de omakase de Hanwoo y consultor internacional de carne. Seminarios desde Singapur hasta Boston, y dieciocho años en el tajo.","meta.about.title":"Perfil · Ron Ko — Carnicero cultural","meta.about.desc":"Yongjae Ko (Ron): treinta y un años de trabajo; diez en compras corporativas y rediseño de procesos, cinco en consultoría financiera y dieciocho en el tajo como carnicero, parrillero y chef de omakase de Hanwoo.","meta.archive.title":"Archivo · Ron Ko — Carnicero cultural","meta.archive.desc":"El registro fotográfico del trabajo de Ron Ko: seminarios de Hanwoo en Hong Kong, Singapur y Laos, una cocina de barbacoa coreana en Boston, la carnicería y los días libres.","meta.contact.title":"Contacto · Ron Ko — Carnicero cultural","meta.contact.desc":"Escribe a Yongjae (Ron) Ko para seminarios de Hanwoo, clases magistrales de carnicería, aperturas de cocina, programas de carne y consultoría de producto.","home.hero.kicker":"Yongjae Ko · Ron","home.hero.title":"Maestro carnicero. Chef de omakase de Hanwoo. <em>Consultor de carne.</em>","home.hero.lede":"De mis treinta y un años de trabajo, dieciocho los he pasado con un cuchillo en la mano: al frente del departamento de carne de la casa de Hanwoo más exigente de Corea, en la barra de omakase de Hanwoo Dining Ulleung, en el distrito de Gangnam de Seúl, y ahora construyendo los productos y los sistemas de una planta de food-tech. Hoy enseño, corto y cocino para socios desde Singapur hasta Boston.","home.hero.ctaWork":"Trabajemos juntos","home.hero.ctaArchive":"Ver el archivo","home.hero.foot":"Vive en Goyang, Corea · Disponible para seminarios, consultoría y aperturas de cocina","home.hero.alt":"Ron Ko, en blanco y negro, pasando el cuchillo por una canal de vacuno colgada","home.hero.caption":"Deshuesando una canal colgada. En lo que sea que se convierta el oficio —un menú, una fábrica, una marca—, empieza aquí.","home.m1":"años como carnicero, parrillero y jefe de cocina","home.m2":"años de carrera, trece de ellos en compras corporativas, rediseño de procesos y finanzas","home.m3":"viajes a Ulleungdo por el ganado Chikso autóctono","home.m4":"países y territorios enseñando, asesorando o abriendo cocinas","home.work.eyebrow":"Proyectos internacionales y viajes de trabajo","home.work.title":"Adónde me ha llevado el trabajo, 2025–2026","home.work.intro":"Cuatro regiones en dos años: una recepción de embajada y una parrilla en una azotea en Singapur, una demostración de carnicería en Hong Kong, la apertura de una cocina de barbacoa coreana en Boston, y seminarios y visitas de mercado por el sudeste asiático.","home.sg.when":"2026 · octubre","home.sg.title":"Hanwoo, de la recepción de la embajada a la parrilla de la azotea","home.sg.place":"Singapur","home.sg.body":"Cinco días de trabajo con la Embajada de Corea, Bidfood y un distribuidor local, que terminaron en una clase magistral al aire libre: los invitados vieron deshacer un solomillo entero y después lo comieron recién salido de la parrilla.","home.sg.f1":"Embajada de Corea en Singapur — recepción del Día de la Fundación Nacional, stand de Hanwoo y servicio","home.sg.f2":"Bidfood Singapur — sesión en el showroom con el equipo de compras","home.sg.f3":"Revisión de anaquel del distribuidor — ibérico y pato ahumados","home.sg.f4":"Clase magistral de Hanwoo al aire libre y cata en la parrilla al anochecer","home.sg.link":"Fotografías de Singapur","home.sg.alt1":"Cocineros asando Hanwoo en una cata nocturna bajo la pancarta verde HANWOO KOREAN BEEF, en Singapur","home.sg.alt2":"Ron Ko cortando un solomillo de Hanwoo entero en una terraza de azotea en Singapur","home.sg.alt3":"Ron Ko en el stand HANWOO durante la recepción de la Embajada de Corea en Singapur","home.hk.when":"2026 · junio","home.hk.title":"Una demostración de carnicería para cocineros y compradores","home.hk.place":"Hong Kong","home.hk.body":"La parte del programa de seminarios de Hanwoo que imparto para la Korea Beef Association: los treinta y nueve cortes explicados con el cuchillo en la mano, ante los cocineros, importadores y compradores que deciden qué llega a sus cartas.","home.hk.f1":"Despiece de un bloque entero en el escenario, con filipina y guantes","home.hk.f2":"Del bloque al subcorte y al corte de servicio, explicado mientras se separa","home.hk.f3":"Emplatado y cata con la cocina anfitriona","home.hk.link":"Fotografías de Hong Kong","home.hk.alt1":"Ron Ko con filipina negra demostrando el despiece de un bloque de Hanwoo en Hong Kong","home.hk.alt2":"Ron Ko y el chef anfitrión saludando a la sala tras la demostración","home.hk.alt3":"Ron Ko con los organizadores y los cocineros tras el seminario de Hong Kong","home.us.when":"2026 · marzo y mayo","home.us.title":"Abrir una cocina de barbacoa coreana en el extranjero","home.us.place":"Boston y Nueva York, EE. UU.","home.us.body":"En Boston trabajé con el equipo de JIN-JEE en lo que una receta no puede transmitir: el corte de músculos enteros, la maduración, el manual de parrilla, el flujo de cocina y la línea de costes que hay debajo. Nueva York, en marzo de 2026, fue un viaje aparte, y sus fotografías también están aquí.","home.us.f1":"JIN-JEE, Boston — limpieza, maduración y técnica de parrilla transmitidas al equipo de cocina","home.us.f2":"Revisión de la línea de cocina, el horno de leña y el flujo del comedor","home.us.f3":"Nueva York, marzo de 2026 — la ciudad, en carrete y en el móvil","home.us.link":"Fotografías de Estados Unidos","home.us.alt1":"Línea de cocina y horno de leña en JIN-JEE, Boston, en carrete","home.us.alt2":"Cena con el equipo de JIN-JEE en Boston","home.us.alt3":"El skyline de Manhattan de noche desde la ventana de un hotel","home.sea.when":"2025 · abril y octubre","home.sea.title":"Seminarios y visitas de mercado por el sudeste asiático","home.sea.place":"Laos · Camboya · Tailandia","home.sea.body":"El año anterior a los viajes americanos: un seminario de Hanwoo en Laos con el corte en la mano y, en abril de 2025, un viaje que pasó por Phnom Penh y Bangkok — sedes, showrooms y las calles corrientes entre ellas.","home.sea.f1":"Laos — seminario de Hanwoo, octubre de 2025","home.sea.f2":"Camboya — visita a la sede y al showroom de Phnom Penh, abril de 2025","home.sea.f3":"Tailandia — Bangkok, abril de 2025","home.sea.link":"Fotografías del sudeste asiático","home.sea.alt1":"Ron Ko presentando un bloque de Hanwoo en un seminario en Laos","home.sea.alt2":"Pantalla de la sala del seminario en Phnom Penh","home.sea.alt3":"Jardín del hotel en Bangkok durante el viaje de 2025","home.chapters.eyebrow":"Capítulos de carrera","home.chapters.title":"Dieciocho años, cortados en capítulos","home.chapters.intro":"La cronología completa, con fechas, está en la página de <a href=\"about.html\">perfil</a>. Estos son los años que hicieron posible el resto.","home.c1.years":"2018 · 2019","home.c1.title":"Born & Bred — jefe del departamento de carne","home.c1.text":"Selección de canales 1++, despiece preciso, cortes especiales y maduración en la casa de Hanwoo premium más exigente de Corea, incluido el deshuesado de una costilla entera ante la sala durante el servicio de omakase.","home.c2.years":"2019 · 2022","home.c2.title":"Soonwoo Black y Hanwoo Dining Ulleung","home.c2.text":"Abrí la sucursal de cuatro plantas de Soonwoo Black en Myeongdong y llevé la barra de omakase de la última planta; después me trasladé a Hanwoo Dining Ulleung, en el distrito de Gangnam de Seúl, donde diseñé y dirigí yo mismo los menús de omakase: menús construidos alrededor del corte, cortado delante del comensal.","home.c3.years":"2020 · 2022","home.c3.title":"Dieciséis travesías a Ulleungdo","home.c3.text":"Dos años, dieciséis cruces, un propósito: el Chikso autóctono. Deshuesé y limpié yo mismo los bloques en el matadero de la isla y los envié por barco al continente, hasta la barra de Hanwoo Dining Ulleung en Seúl. Sin intermediarios.","home.c4.years":"2022 · 2023","home.c4.title":"Gwangpyung Meat — director","home.c4.text":"Dos cámaras de maduración en seco, charcutería, embutido y jamón crudo, el lanzamiento del cerdo Nangchuk Matdon y el suministro de vacuno y porcino a marcas de restauración y a cajas de regalo de temporada.","home.c5.years":"2023 · hoy","home.c5.title":"Una startup de food-tech — CPO y director socio","home.c5.text":"Una línea de bulgogi listo para calentar, bajo en azúcar y alto en proteína —1,6 g de azúcares y hasta 39 g de proteína por 100 g—, una planta HACCP y el ERP de fábrica y la app de campo que construí yo solo con IA: 457 commits, desde la recepción de mercancía hasta la trazabilidad por lote y el coste real por partida.","home.c6.years":"2024 · en curso","home.c6.title":"I+D y la barra de cata","home.c6.text":"Productos llevados de la especificación a la barra de cata —líneas listas para calentar, un programa de maduración y charcutería y el suministro OEM que hay detrás. Aquí se ve que el carnicero y el responsable de producto son la misma persona.","home.c7.years":"2026 · en progreso","home.c7.title":"Escribir el Archivo de Humanidades de la Carne","home.c7.text":"Siete investigaciones sobre la historia de la carne —la domesticación, el cerdo coreano premoderno, la mejora de razas y por qué este país corta la ternera fina y la asa a fuego vivo— y un manuscrito que se escribe a partir de ellas.","home.wide.caption":"Stand de cata y consulta: el lado de producto del oficio, donde una especificación se encuentra con el paladar de un cliente.","home.wide.meta":"Corea · 2024.07","home.wide.alt":"Stand de cata y consulta de producto en una feria alimentaria, con el equipo tras el mostrador","home.services.eyebrow":"Lo que hago","home.services.title":"Tres cosas, con las mismas manos","home.s1.title":"Carnicería y programas de carne","home.s1.text":"Despiece de canales, rendimiento y coste, maduración en seco y húmeda, charcutería, y los procedimientos que mantienen una cocina constante cuando yo no estoy de pie en ella.","home.s1.i1":"Despiece de canal y de bloques","home.s1.i2":"Maduración, charcutería, salazón","home.s1.i3":"Rendimiento, coste y estructura de carta","home.s2.title":"Clases magistrales y seminarios de Hanwoo","home.s2.text":"Para cocineros, importadores, distribuidores y ferias: los cortes explicados con el cuchillo en la mano, en coreano, en inglés o con intérprete —el mismo programa que imparto en el extranjero para la Korea Beef Association.","home.s2.i1":"Seminarios B2B y ferias","home.s2.i2":"Demostración de carnicería en vivo","home.s2.i3":"Formación de cocineros y compradores","home.s3.title":"Consultoría de restauración y producto","home.s3.text":"Aperturas de restaurante, flujo de cocina, manuales de parrilla, estructura de costes y, en el lado industrial, desarrollo de producto listo para calentar, procesos HACCP y los sistemas digitales que los sostienen.","home.s3.i1":"Diseño de cocina y servicio","home.s3.i2":"Desarrollo de producto RTH / OEM","home.s3.i3":"Implantación de planta HACCP y ERP","home.quote.text":"«La historia de un pueblo se escribe en la manera de cortar un animal.»","home.quote.cite":"Archivo de Humanidades de la Carne · en progreso","home.closing.p1":"Lo último que quiero construir no es un restaurante ni un producto. Es un libro sobre por qué los coreanos cortan la ternera fina, la asan a fuego vivo y comen el animal hasta la última capa, escrito desde el tajo, el matadero y el archivo, no desde el orgullo nacional.","home.closing.p2":"Las siete investigaciones están hechas: la historia de las razas, el cerdo coreano premoderno, los hechos detrás de los relatos del «origen del wagyu» y de la «exportación del samgyeopsal», los colores del ganado en los registros antiguos y cómo China, Europa y Corea convirtieron cada una un animal en una cocina. El manuscrito se escribe ahora.","home.closing.cta":"Leer sobre el proyecto","home.cta.eyebrow":"Contacto","home.cta.title":"¿Hablamos de carne?","home.cta.text":"Un seminario que impartir, una cocina que abrir, un producto que poner en un estante o un corte que nadie en la sala sepa nombrar: escríbeme y cuéntame en qué estás trabajando.","home.cta.more":"Otras formas de contactarme","about.eyebrow":"Perfil","about.title":"Treinta y un años, y el cuchillo llegó segundo.","about.portraitAlt":"Ron Ko cortando un solomillo de Hanwoo entero al aire libre en Singapur, con el skyline de la ciudad detrás","about.portraitCaption":"Singapur, octubre de 2026. Cortando un solomillo entero en una clase magistral al aire libre.","about.p1":"Pasé los primeros trece años de mi vida laboral dentro de sistemas. Desde 1995 estuve en el departamento de compras de una constructora cotizada —acero, hormigón, chapa, ofertas de subcontratistas— y luego en el equipo de rediseño de procesos de toda la empresa, que desmontaba el proceso de cada departamento, lo rediseñaba y lo llevaba a un ordenador. De 2003 a 2007 vendí productos financieros, que enseña a sentarse delante de un desconocido y explicar algo difícil con palabras sencillas.","about.p2":"En octubre de 2007 entré en un mercado de carne para aprender un oficio con las manos. Dieciocho meses en canales de cerdo, un año en vacuno. Después fábricas y plantas, y de nuevo las salas: una casa de Hanwoo premium, la barra de omakase de Hanwoo Dining Ulleung en Seúl, dieciséis viajes al matadero de Ulleungdo por el Chikso autóctono, un programa de charcutería y ahora una startup de food-tech donde soy el director de producto.","about.p3":"No soy un cocinero que se puso a hacer negocios ni un empresario al que le gusta la comida. Soy un carnicero que pasó antes una década dentro de sistemas corporativos, y esa combinación es el trabajo: un oficio que se puede enseñar, costear, escribir y repetir.","about.stat1":"años trabajando","about.stat2":"de ellos con un cuchillo","about.stat3":"antes en sistemas corporativos","about.timeline.eyebrow":"Cronología","about.timeline.title":"Una carrera, en orden","about.timeline.intro":"Cada fecha es el mes en que empecé y terminé de verdad. Donde hay un hueco, no fue un camino recto.","about.era1":"2023 — hoy","about.era2":"2013 — 2023","about.era3":"2007 — 2012","about.era4":"1995 — 2007","about.r1.years":"2023.12 – hoy","about.r1.role":"CPO y director socio, una startup de food-tech","about.r1.small":"Línea de bulgogi listo para calentar, bajo en azúcar y alto en proteína; planta HACCP; ERP de fábrica y app de campo construidos solo con IA (457 commits).","about.r2.years":"2026 – hoy","about.r2.role":"Escribiendo el Archivo de Humanidades de la Carne","about.r2.small":"Siete investigaciones terminadas; el manuscrito está en curso.","about.r3.years":"2022.06 – 2023.11","about.r3.role":"Director, Gwangpyung Meat","about.r3.small":"Dos cámaras de maduración en seco, charcutería, embutido y jamón crudo; lanzamiento del cerdo Nangchuk Matdon; suministro a marcas de restauración y cajas de regalo.","about.r4.years":"2020.05 – 2022.06","about.r4.role":"Gerente de sucursal, Hanwoo Dining Ulleung","about.r4.small":"Menús de omakase planificados y dirigidos en la barra de Hanwoo Dining Ulleung, en Gangnam (Seúl); dieciséis viajes a Ulleungdo por el Chikso autóctono, deshuesado en el matadero de la isla y enviado por barco al continente.","about.r5.years":"2019.08 – 2020.05","about.r5.role":"Gerente de sucursal, Soonwoo Black, Myeongdong","about.r5.small":"Abrí la sucursal de cuatro plantas y llevé la barra de omakase premium de la última planta.","about.r6.years":"2018.09 – 2019.08","about.r6.role":"Jefe del departamento de carne, Born & Bred","about.r6.small":"Selección 1++, despiece preciso de canales, cortes especiales y maduración en la casa de Hanwoo premium de Corea.","about.r7.years":"2013 – 2018","about.r7.role":"Años de cocinas independientes","about.r7.small":"Jefe de carnicería en un restaurante de barbacoa coreana (2014); gestión de un local de barbacoa autoservicio en Paju (2015); jefe de carnicería y parrillero en una casa de Hanwoo (2016–17).","about.r8.years":"2012.03 – 2012.10","about.r8.role":"Jefe de planta, Ocentic Meat","about.r8.small":"Hamburguesas, embutido artesanal y filetes: primera y segunda transformación, proceso e higiene.","about.r9.years":"2010.04 – 2011.12","about.r9.role":"Jefe de producción, GM Livestock","about.r9.small":"De cuatro a seis canales al día; despiece preciso y segunda transformación en una planta dedicada.","about.r10.years":"2009.03 – 2010.03","about.r10.role":"Jefe de equipo de carne, Aurim Hanwoo Village","about.r10.small":"Despiece de Hanwoo para un restaurante-carnicería; cajas de regalo B2B para los polígonos cercanos.","about.r11.years":"2007.10 – 2009.03","about.r11.role":"Departamento de carne, Gyoha Meat Market","about.r11.small":"Donde empezó: canales de cerdo durante dieciocho meses, vacuno durante un año.","about.r12.years":"2003.05 – 2007.09","about.r12.role":"Consultor financiero, ING Life","about.r12.small":"Planificación financiera personal y corporativa.","about.r13.years":"1995.03 – 2003.04","about.r13.role":"Compras y rediseño de procesos, Goryeo Development (grupo Daerim)","about.r13.small":"Compra de materiales a gran escala —acero, hormigón, chapa— y después el rediseño de procesos de toda la empresa y el ERP que lo siguió.","about.note":"Formación: Universidad Myongji, Comercio (1989–1994). Además de los viajes fotografiados en el <a href=\"archive.html\">archivo</a>: instructor oficial de Hanwoo de la Korea Beef Association en Hong Kong, Singapur y Laos, y consultoría de cocinas K-BBQ en Boston, 2026.","about.off.eyebrow":"Fuera del horario","about.off.title":"Aficiones y viajes","about.off.intro":"Lo que llena los días en que no estoy de pie ante un tajo: carretera, campo, carrete y familia.","about.cycling.label":"Ciclismo","about.cycling.text":"Sobre todo carretera. La fotografía antigua del archivo es de la cima del puerto de Misiryeong, y sigo usando esa subida como medida del año.","about.cycling.alt":"Ron Ko con casco de ciclista antes de una salida","about.golf.label":"Golf","about.golf.text":"Siempre que el calendario lo permite: el único juego en el que un mal día sigue siendo cuatro horas al aire libre.","about.golf.alt":"Ron Ko en un campo de golf","about.film.label":"Fotografía analógica","about.film.text":"Una cámara analógica vieja viaja en cada viaje. Varias de las fotos de Boston y Nueva York de este sitio están hechas con ella.","about.film.alt":"Ron Ko con una cámara analógica antigua","about.japan.label":"Viaje · Japón 2025","about.japan.text":"Nagoya con mi familia: una tienda de cuchillos en la que me habría quedado toda la tarde y las exposiciones sobre la historia de las razas Matsusaka y Tajima.","about.japan.alt":"Interior de una tienda de cuchillos en Nagoya","about.extra.p1":"El café es de filtro, y las dos bolsas a las que siempre vuelvo son Kenia AA y Etiopía lavado: discutiré sobre la temperatura del agua antes que sobre cualquier otra cosa en una cocina.","about.extra.p2":"El resto del tiempo libre va a leer para el <a href=\"archive.html#writing\">Archivo de Humanidades de la Carne</a>: registros antiguos, libros de razas y los relatos de quienes anotaron lo que comía un pueblo.","about.quote.text":"«El cuchillo es una herramienta. Saber qué corte recordará un comensal es el oficio.»","about.quote.cite":"Ron Ko","about.cta.contact":"Escríbeme","about.cta.archive":"Ver el archivo","archive.eyebrow":"Archivo","archive.title":"Un registro, en orden","archive.lede":"Seminarios, clases magistrales, cocinas, plantas y algún día libre. Cada fotografía lleva el día y el lugar en que se tomó; cuando la fecha se desconoce, no se pone ninguna.","archive.filterLabel":"Filtrar el archivo","filter.all":"Todo","filter.trips":"Viajes y seminarios","filter.craft":"Carnicería, sala e I+D","filter.travel":"Viajes y aficiones","archive.empty":"Se están añadiendo fotografías; vuelve en un rato.","archive.writing.eyebrow":"Escritura · Archivo de Humanidades de la Carne","archive.writing.title":"La carne, escrita","archive.writing.p1":"Un proyecto de largo aliento sobre la historia y la cultura de la carne: desde la domesticación de vacunos y cerdos hasta por qué los cocineros coreanos cortan la ternera fina, la asan a fuego vivo y comen el animal hasta la última capa.","archive.writing.p2":"La tesis no es que la carne de un país sea la mejor. Es que la manera en que un pueblo corta, cocina y come un animal lleva su historia, y que ese registro merece leerse de cerca en lugar de repetirse.","archive.status.research":"Investigación","archive.status.researchText":"Siete trabajos terminados y ordenados por tema: razas y ganado autóctono, el cerdo coreano premoderno, registros antiguos, los relatos del «origen del wagyu» y de la «exportación del samgyeopsal» contrastados con las fuentes, y los métodos de despiece y cocina.","archive.status.manuscript":"Manuscrito","archive.status.manuscriptText":"Introducción y prólogo redactados y en revisión a mano, sección por sección.","archive.status.next":"Siguiente","archive.status.nextText":"Textos breves extraídos del archivo y, después, un libro.","archive.quote.text":"«¿Por qué tan fino? ¿Por qué al fuego? ¿Por qué la última capa del animal y no la primera?»","archive.quote.cite":"Las tres preguntas con las que empieza el libro","archive.instagram":"El trabajo del día a día en Instagram","contact.eyebrow":"Contacto","contact.title":"Hablemos de carne.","contact.lede":"Un seminario que impartir, una clase magistral que dirigir, una cocina que abrir, un producto que poner en un estante o un corte que nadie en la sala sepa nombrar: cuéntame en qué estás trabajando y te diré con honestidad si soy la persona adecuada.","contact.known.label":"Conviene saber","contact.known.text":"En el primer mensaje ayuda incluir: el evento o proyecto, la fecha y la ciudad, el público o el menú que tienes en mente y si se pueden publicar fotografías del trabajo.","contact.card.name":"Yongjae Ko · Ron","contact.card.role":"Maestro carnicero, chef de omakase de Hanwoo y consultor de carne.","contact.email.label":"Correo","contact.email.small":"La forma más fiable de contactarme.","contact.based.label":"Base","contact.based.value":"Goyang, Corea","contact.based.small":"Área metropolitana de Seúl · GMT+9","contact.working.label":"Dónde trabajo","contact.working.value":"Asia y Estados Unidos","contact.working.small":"Seminarios, clases magistrales, aperturas de cocina, desarrollo de producto","contact.sessions.label":"Idiomas","contact.sessions.value":"Coreano o inglés","contact.sessions.small":"Se puede organizar interpretación","contact.youtube.label":"YouTube","contact.youtube.small":"Notas de campo desde la planta y la carretera","contact.writing.label":"Escritura","contact.writing.value":"Archivo de Humanidades de la Carne","contact.writing.small":"En progreso","contact.before.eyebrow":"Antes de escribir","contact.before.title":"Tres cosas que conviene saber","contact.q1.title":"¿Viajas?","contact.q1.text":"Sí. En los últimos dos años he enseñado y asesorado en Hong Kong, Singapur, Laos, Camboya y Estados Unidos, y viajo con facilidad cuando el trabajo lo pide.","contact.q2.title":"¿Trabajas también con cerdo y cordero?","contact.q2.text":"Sí. La reputación la he construido con el vacuno, pero aprendí el oficio en canales de cerdo y he dirigido plantas que procesan vacuno, cerdo y cordero, incluidos programas de charcutería y maduración en seco.","contact.q3.title":"¿Puedes trabajar en una fábrica además de en una cocina?","contact.q3.text":"Esa es la parte poco habitual de mi currículum: implantación de plantas HACCP, procedimientos, rendimiento y coste, desarrollo de producto listo para calentar y los sistemas digitales que lo registran todo.","contact.cta.eyebrow":"O empieza aquí","contact.cta.title":"Mira primero el trabajo","contact.cta.text":"Cuatro regiones, dos años y un registro que indica el día y el lugar de cada fotografía.","contact.cta.b1":"Abrir el archivo","contact.cta.b2":"Leer la carrera","gallery.count":"{n} fotografías","lightbox.viewer":"Visor de fotos","lightbox.viewerTitled":"Visor de fotos: {title}","lightbox.close":"Cerrar el visor de fotos","lightbox.prev":"Foto anterior","lightbox.next":"Foto siguiente","lightbox.open":"Abrir foto","lightbox.openTitled":"Abrir foto: {title}"}};
